//! Racket: `azul.rkt` (generated by `doc/src/codegen/v2/lang_racket`,
//! `ffi/unsafe`, `(require "azul.rkt")`).
//!
//! Spellings: every function has a kebab-case wrapper `<class>-<method>`
//! (`(css-property-text-color x)`, variant constructors `(layout-width-px pv)`,
//! `(layout-width-auto)`), C-like enum members are integer constants
//! `AzLayoutDisplay_Flex`, structs are `define-cstruct`s built positionally
//! (`(make-AzColorU 255 0 0 255)`), a hand-built union variant is its
//! variant struct's fields set BY NAME in the union's memory (`css-union`
//! below: `set-AzLayoutWidthValue_Variant_Exact-variant-tag!` / `-payload!`),
//! never the positional `make-..._Variant_..`, whose argument list also has
//! the padding the binding puts between tag and payload. A Vec is copied
//! from a `malloc`ed array (`css-vec`), a string is
//! `(string->azul-string "..")`.
//!
//! DOM export: a builder method is its kebab wrapper taking `self` first,
//! nested (`(dom-with-child dom child)`); parameters are optional with the
//! component's defaults, Racket strings converted by `string->azul-string`
//! where they are used; a joined string is `(string->azul-string
//! (string-append "by " author))`. The app follows `examples/racket`
//! (`window-create-options-create` registers the layout callback). The
//! registration's render functions are real C function pointers
//! (`function-ptr`: libffi callbacks, which return the result struct by
//! value); the library function goes through the binding's host invoker
//! (`app-config-add-component-library`). A component instance is a call of
//! its render function (`(render-badge tag)`, Racket strings as arguments).

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use core::fmt::Write;

use crate::codegen::{
    doc::{render, Doc},
    ir::{
        snake_to_lower_camel, ComponentSpec, EnumShape, Expr, Ident, Item, LibrarySpec, Module,
        Prim,
    },
    lang::{
        dom::one_line, escape_quoted, expr_doc, item_comments, item_doc, module_any, unicode_u4,
        variant_ctor_method, ConcatPart, ExprSyntax, MethodLayout,
    },
    CodegenBackend, GeneratedFile,
};

/// The Racket printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Racket;

/// `sanitize_racket_ident` of `lang_racket/mod.rs`.
const RESERVED: &[&str] = &[
    "define", "lambda", "let", "let*", "letrec", "if", "cond", "case", "when", "unless", "begin",
    "set!", "quote", "quasiquote", "require", "provide", "struct", "and", "or", "do", "for",
    "map", "list", "car", "cdr", "else",
];

/// `kebab` of `lang_racket/mod.rs`.
fn kebab(name: &str) -> String {
    let mut out = String::new();
    let mut prev_lower = false;
    let mut prev_digit = false;
    for c in name.chars() {
        if c == '_' || c == '-' {
            if !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            prev_lower = false;
            prev_digit = false;
        } else if c.is_uppercase() {
            if (prev_lower || prev_digit) && !out.is_empty() && !out.ends_with('-') {
                out.push('-');
            }
            out.push(c.to_ascii_lowercase());
            prev_lower = false;
            prev_digit = false;
        } else {
            out.push(c);
            prev_lower = c.is_ascii_lowercase();
            prev_digit = c.is_ascii_digit();
        }
    }
    while out.contains("--") {
        out = out.replace("--", "-");
    }
    if RESERVED.contains(&out.as_str()) {
        format!("{out}_")
    } else {
        out
    }
}

/// `public_name` of `lang_racket/wrappers.rs` (never `new` here).
fn wrapper(class: &str, c_method: &str) -> String {
    format!("{}-{}", kebab(class), kebab(c_method))
}

/// `(f a b)`, one argument per line when `broken`.
fn form(f: String, args: Vec<Doc>, broken: bool) -> Doc {
    if args.is_empty() {
        return Doc::text(format!("({f})"));
    }
    let open = if broken {
        format!("({f}")
    } else {
        format!("({f} ")
    };
    Doc::list(&open, args, " ", ")", false, broken, false)
}

/// A Racket string literal (`\u` / `\U` escapes keep it ASCII).
fn quoted(s: &str) -> String {
    format!("\"{}\"", escape_quoted(s, &[], &unicode_u4))
}

/// A parameter's Racket name (a reserved name gets a `_`).
fn rkt_param(name: &Ident) -> String {
    kebab(&name.snake())
}

impl ExprSyntax for Racket {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "+nan.0".to_string(),
            "inf" => "+inf.0".to_string(),
            "-inf" => "-inf.0".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "#t" } else { "#f" })
    }

    fn string(&self, s: &str) -> Doc {
        form("string->azul-string".to_string(), vec![Doc::text(quoted(s))], false)
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        form(wrapper(class, &snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            EnumShape::Tagged => form(wrapper(ty, &variant_ctor_method(variant)), args, broken),
            // By field name: see `CSS_UNION`.
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let vs = format!("Az{ty}_Variant_{variant}");
                let mut parts = vec![
                    Doc::text(format!("_Az{ty}")),
                    Doc::text(format!("{vs}-tag")),
                    Doc::text(format!("set-{vs}-variant-tag!")),
                    Doc::text(format!("Az{ty}_Tag_{variant}")),
                ];
                if let Some(payload) = args.into_iter().next() {
                    parts.push(Doc::text(format!("set-{vs}-payload!")));
                    parts.push(payload);
                }
                form("css-union".to_string(), parts, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let values = fields.into_iter().map(|(_, v)| v).collect();
        form(format!("make-Az{ty}"), values, broken)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return form(wrapper(ty, "create"), Vec::new(), false);
        }
        form(
            "css-vec".to_string(),
            vec![
                Doc::text(wrapper(ty, "copyFromPtr")),
                Doc::text(format!("_Az{elem}")),
                form("list".to_string(), items, broken),
            ],
            broken,
        )
    }

    fn unsupported(&self, what: &str) -> Doc {
        form(
            "error".to_string(),
            vec![Doc::text(quoted(&format!("not expressible: {what}")))],
            false,
        )
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `(dom-with-child recv child)`: the wrapper takes `self` first; a
    /// chain nests.
    fn method(&self, recv: Doc, class: &str, method: &str, args: Vec<Doc>, layout: MethodLayout) -> Doc {
        let mut all = vec![recv];
        all.extend(args);
        form(wrapper(class, &snake_to_lower_camel(method)), all, layout.node_tall)
    }

    fn param(&self, name: &Ident) -> Doc {
        form("string->azul-string".to_string(), vec![Doc::text(rkt_param(name))], false)
    }

    /// `(string->azul-string (string-append "by " author))`.
    fn concat(&self, parts: &[ConcatPart<'_>]) -> Doc {
        form("string->azul-string".to_string(), vec![string_append(parts)], false)
    }

    fn item_call_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `(render-card "Hi" title)`: another function of the module.
    fn item_call(&self, item: &Ident, args: Vec<Doc>, broken: bool) -> Doc {
        form(fn_name_of(item), args, broken)
    }

    /// A Racket string: a literal, a parameter passed on, or
    /// `(string-append "by " author)`.
    fn native_string(&self, parts: &[ConcatPart<'_>]) -> Doc {
        match parts {
            [] => Doc::text(quoted("")),
            [ConcatPart::Lit(s)] => Doc::text(quoted(s)),
            [ConcatPart::Param(p)] => Doc::text(rkt_param(p)),
            _ => string_append(parts),
        }
    }
}

/// `(string-append "by " author)`: a Racket string joined from `parts`.
fn string_append(parts: &[ConcatPart<'_>]) -> Doc {
    let args: Vec<Doc> = parts
        .iter()
        .map(|p| match p {
            ConcatPart::Lit(s) => Doc::text(quoted(s)),
            ConcatPart::Param(i) => Doc::text(rkt_param(i)),
        })
        .collect();
    form("string-append".to_string(), args, false)
}

/// `(name [title "Hello"] ..)`: parameters are optional with their
/// defaults (a String default is the Racket string).
fn header(name: &str, item: &Item) -> String {
    let mut out = format!("({name}");
    for p in &item.params {
        match &p.default {
            Some(Expr::Str(d)) => {
                let _ = write!(out, " [{} {}]", rkt_param(&p.name), quoted(d));
            }
            Some(d) => {
                let _ = write!(out, " [{} {}]", rkt_param(&p.name), expr_doc(&Racket, d).flat());
            }
            None => {
                let _ = write!(out, " {}", rkt_param(&p.name));
            }
        }
    }
    out.push(')');
    out
}

const CSS_VEC: &str = r";; Copies ITEMS into a malloc'ed array of TYPE; COPY clones them into a Vec.
(define (css-vec copy type items)
  (define n (length items))
  (define arr (malloc (max 1 n) type))
  (for ([item (in-list items)] [i (in-naturals)])
    (ptr-set! arr type i item))
  (copy arr n))
";

/// The union helper. It sets the variant struct's fields by name (through
/// the `define-cstruct` setters, on the union memory tagged as the variant
/// struct), so the padding the binding puts between `variant-tag` and
/// `payload` (where Rust puts the payload) needs no value here.
const CSS_UNION: &str = r";; A union value of TYPE holding one variant. The variant struct's `variant-tag`
;; and `payload` are set by name (VARIANT-TAG is the struct's pointer tag), so
;; the padding the binding puts between them needs no value.
(define (css-union type variant-tag set-tag! tag [set-payload! #f] [payload #f])
  (define p (malloc type))
  (cpointer-push-tag! p variant-tag)
  (set-tag! p tag)
  (when set-payload! (set-payload! p payload))
  (ptr-ref p type))
";

fn fn_name(item: &Item) -> String {
    fn_name_of(&item.name)
}

/// [`fn_name`] of the item named `name`.
fn fn_name_of(name: &Ident) -> String {
    name.kebab()
}

/// What the registration calls (only when a component takes parameters).
const REGISTRATION_HELPERS: &str = r";; The String value of the data-model field NAME, or FALLBACK.
(define (model-string model name fallback)
  (define fields (AzComponentDataModel-fields model))
  (let loop ([i 0])
    (cond
      [(>= i (AzComponentDataFieldVec-len fields)) fallback]
      [else
       (define f (ptr-ref (AzComponentDataFieldVec-ptr fields) _AzComponentDataField i))
       (define some (union-ref (AzComponentDataField-default-value f) 1))
       (define value (union-ref (AzOptionComponentDefaultValue_Variant_Some-payload some) 1))
       (if (and (equal? (azul-string->string (AzComponentDataField-name f)) name)
                (= (AzOptionComponentDefaultValue_Variant_Some-variant-tag some)
                   AzOptionComponentDefaultValue_Tag_Some)
                (= (AzComponentDefaultValue_Variant_String-variant-tag value)
                   AzComponentDefaultValue_Tag_String))
           (azul-string->string (AzComponentDefaultValue_Variant_String-payload value))
           (loop (add1 i)))])))

;; A String field of a component's data model.
(define (string-field name value description)
  (make-AzComponentDataField
   (string->azul-string name)
   (component-field-type-string)
   (option-component-default-value-some (component-default-value-string (string->azul-string value)))
   #f
   (string->azul-string description)))
";

/// The registration of a component library (`m.library`): per component a
/// default-arguments wrapper, a render function made a C function pointer
/// with `function-ptr` (kept alive by its module-level definition), and its
/// `ComponentDef` (built positionally; code calls the component through its
/// render function: `ComponentCodegen::RenderFunction`); then
/// `register-<library>-library`,
/// which `app-config-add-component-library` takes (through the binding's
/// host invoker). Items the module does not have are skipped.
fn racket_registration(m: &Module, lib: &LibrarySpec) -> String {
    let lk = Ident::from_text(&lib.name).kebab();
    let az = |s: &str| format!("(string->azul-string {})", quoted(s));
    let components: Vec<(&ComponentSpec, &Item)> = lib
        .components
        .iter()
        .filter_map(|c| m.item(&c.item).map(|i| (c, i)))
        .collect();
    let mut s = String::from("\n;; -- registration --\n");
    if components.iter().any(|(_, i)| !i.params.is_empty()) {
        s.push('\n');
        s.push_str(REGISTRATION_HELPERS);
    }
    let mut defs: Vec<String> = Vec::new();
    for (c, item) in &components {
        let item_fn = fn_name(item);
        let ck = Ident::from_text(&c.name).kebab();
        let defaults: Vec<String> = item.params.iter().map(|p| quoted(p.default_text())).collect();
        let call = if defaults.is_empty() {
            format!("({item_fn})")
        } else {
            format!("({item_fn} {})", defaults.join(" "))
        };
        let _ = write!(
            s,
            "\n;; `{}:{}` with its default arguments.\n(define ({item_fn}-default)\n  {call})\n",
            one_line(&lib.name),
            one_line(&c.name)
        );
        let args: Vec<String> = item
            .params
            .iter()
            .map(|p| {
                format!(
                    "(model-string m {} {})",
                    quoted(&p.name.snake()),
                    quoted(p.default_text())
                )
            })
            .collect();
        let render_call = if args.is_empty() {
            format!("({item_fn})")
        } else {
            format!("({item_fn} {})", args.join(" "))
        };
        let _ = write!(
            s,
            "\n(define {ck}-render-fn\n  (function-ptr\n   (lambda (def model component-map)\n     \
             (define m (ptr-ref model _AzComponentDataModel))\n     \
             (result-styled-dom-render-dom-error-ok (styled-dom-create-from-dom {render_call})))\n   \
             (_fun _pointer _pointer _pointer -> _AzResultStyledDomRenderDomError)))\n"
        );
        let fields = if item.params.is_empty() {
            "(component-data-field-vec-create)".to_string()
        } else {
            let mut f = String::from(
                "(css-vec\n     component-data-field-vec-copy-from-ptr\n     \
                 _AzComponentDataField\n     (list",
            );
            for (i, p) in item.params.iter().enumerate() {
                let desc = c.field_descriptions.get(i).map_or("", String::as_str);
                let _ = write!(
                    f,
                    "\n      (string-field {} {} {})",
                    quoted(&p.name.snake()),
                    quoted(p.default_text()),
                    quoted(desc)
                );
            }
            f.push_str("))");
            f
        };
        let _ = write!(
            s,
            "\n(define ({ck}-def)\n  (make-AzComponentDef\n   (component-id-create {} {})\n   \
             {}\n   {}\n   ;; The CSS is applied per node by {item_fn}.\n   {}\n   \
             AzComponentSource_UserDefined\n   (make-AzComponentDataModel\n    {}\n    {}\n    \
             {fields})\n   {ck}-render-fn\n   {}\n   (option-string-none)))\n",
            az(&lib.name),
            az(&c.name),
            az(&c.display_name),
            az(&c.description),
            az(""),
            az(&c.data_model),
            az(&c.data_model_description),
            // `(component-codegen-render-function)`
            Racket
                .variant("ComponentCodegen", EnumShape::Tagged, "RenderFunction", Vec::new(), false)
                .flat(),
        );
        defs.push(format!("({ck}-def)"));
    }
    let components = if defs.is_empty() {
        "(component-def-vec-create)".to_string()
    } else {
        format!(
            "(css-vec component-def-vec-copy-from-ptr _AzComponentDef (list {}))",
            defs.join(" ")
        )
    };
    let _ = write!(
        s,
        "\n;; The component library `{}`:\n;;   (app-config-add-component-library config {} \
         register-{lk}-library)\n(define (register-{lk}-library)\n  (make-AzComponentLibrary\n   \
         {}\n   {}\n   {}\n   {components}\n   #t\n   #f\n   (component-data-model-vec-create)\n   \
         (component-enum-model-vec-create)))\n",
        one_line(&lib.name),
        az(&lib.name),
        az(&lib.name),
        az(&lib.version),
        az("Exported from AzBuilder"),
    );
    s
}

fn is_union(e: &Expr) -> bool {
    matches!(
        e,
        Expr::Variant {
            shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
            ..
        }
    )
}

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&Racket, item) {
        out.push_str(&format!(";; {line}\n"));
    }
    let name = fn_name(item);
    match item_doc(&Racket, item) {
        Ok(doc) => {
            out.push_str(&format!(
                "(define {}\n  {})\n",
                header(&name, item),
                render(&doc, "  ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                ";; {name}: not expressible with the Racket bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Racket {
    fn lang(&self) -> &'static str {
        "racket"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["rkt"]
    }

    fn display_name(&self) -> &'static str {
        "Racket"
    }

    fn extension(&self) -> &'static str {
        "rkt"
    }

    fn emit_module(&self, m: &Module) -> String {
        let fns: Vec<(bool, String, String)> = m
            .items
            .iter()
            .map(|i| {
                let (ok, body) = item_fn(i);
                (ok, fn_name(i), body)
            })
            .collect();
        let mut out = String::from(
            "#lang racket/base\n;; Generated by azul-css codegen (Racket). Do not edit by \
             hand.\n(require ffi/unsafe \"azul.rkt\")\n(provide",
        );
        for (ok, name, _) in &fns {
            if *ok {
                out.push_str(&format!(" {name}"));
            }
        }
        if let Some(lib) = &m.library {
            out.push_str(&format!(" register-{}-library", Ident::from_text(&lib.name).kebab()));
        }
        out.push_str(")\n");
        if m.library.is_some() || module_any(m, &|e| matches!(e, Expr::Vec { .. })) {
            out.push('\n');
            out.push_str(CSS_VEC);
        }
        if module_any(m, &is_union) {
            out.push('\n');
            out.push_str(CSS_UNION);
        }
        for (_, _, body) in &fns {
            out.push('\n');
            out.push_str(body);
        }
        if let Some(lib) = &m.library {
            out.push_str(&racket_registration(m, lib));
        }
        out
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        if let Some(app) = &m.app {
            let root = format!("({})", app.root.kebab());
            let value = if app.is_body {
                root
            } else {
                format!("(dom-with-child (dom-create-body) {root})")
            };
            let main = format!(
                "#lang racket/base\n;; {} - generated by AzBuilder (azul-css codegen, Racket).\n;; \
                 Copy target/codegen/azul.rkt and libazul here, then:\n;;   AZ_LIB_DIR=. racket \
                 main.rkt\n(require \"azul.rkt\" \"ui.rkt\")\n\n;; The layout callback: the root \
                 item.\n(define (layout data-ptr info-ptr)\n  {value})\n\n(define (run-app)\n  (define \
                 app (app-create (refany-create (box 0)) (app-config-create)))\n  (define wco \
                 (window-create-options-create layout))\n  (set-AzFullWindowState-title! \
                 (AzWindowCreateOptions-window-state wco) (string->azul-string {}))\n  (app-run app \
                 wco))\n\n(run-app)\n",
                one_line(&app.title),
                quoted(&app.title),
            );
            return vec![
                GeneratedFile {
                    path: "ui.rkt".to_string(),
                    contents: self.emit_module(m),
                },
                GeneratedFile {
                    path: "main.rkt".to_string(),
                    contents: main,
                },
            ];
        }
        let mut main = String::from(
            "#lang racket/base\n;; Copy target/codegen/azul.rkt and libazul here, then:\n;;   \
             AZ_LIB_DIR=. racket main.rkt\n(require \"azul.rkt\" \"styles.rkt\")\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = fn_name(item);
            main.push_str(&format!(
                "\n(define {name}-value ({name}))\n(printf \"{name}: ~a properties~n\" (Az{}-len \
                 {name}-value))\n",
                item.ty
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.rkt".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.rkt".to_string(),
                contents: main,
            },
        ]
    }
}
